.assistant-surface {
  --assistant-bg: #fff;
  --assistant-surface: #fff;
  --assistant-raised: #f7f9fc;
  --assistant-ink: #192b45;
  --assistant-muted: #617187;
  --assistant-line: #e0e7ef;
  --assistant-accent: #2563eb;
  --assistant-danger: #dc2626;
  --assistant-ok: #10b981;
  --assistant-warn: #f59e0b;
  /* The bar is glass over whatever it floats on, so it needs its own veil. */
  --assistant-veil: rgba(255, 255, 255, 0.82);
  --assistant-veil-line: rgba(24, 43, 69, 0.09);
  --assistant-bar-h: 42px;
  color: var(--assistant-ink);
  background: var(--assistant-bg);
  border: 1px solid var(--assistant-line);
  border-radius: var(--radius-lg, 8px);
  overflow: hidden;
  box-shadow: 0 18px 40px -16px rgba(15, 23, 42, 0.22), 0 2px 4px rgba(15, 23, 42, 0.04);
  font-optical-sizing: auto;
  min-width: 0;
  min-height: 0;
}
.dark .assistant-surface {
  --assistant-bg: #111925;
  --assistant-surface: #182333;
  --assistant-raised: #1d2a3c;
  --assistant-ink: #e2ebf7;
  --assistant-muted: #9aabc1;
  --assistant-line: #2a384c;
  --assistant-accent: #76a5ff;
  --assistant-veil: rgba(13, 20, 32, 0.78);
  --assistant-veil-line: rgba(226, 235, 247, 0.1);
}
.assistant-dock { width: min(520px, 100vw); max-width: 100%; min-height: 0; }

/* ======================================================================
   The top bar
   A single thin row that floats over the transcript: identity on the
   left, state and actions on the right, nothing in the middle. It slides
   out of the way on a downward scroll and returns the instant the user
   scrolls back, reaches for it, or opens one of its panels.
   ====================================================================== */
.assistant-bar {
  position: absolute;
  inset: 0 0 auto 0;
  z-index: 20;
  height: var(--assistant-bar-h);
  display: flex;
  align-items: center;
  color: var(--assistant-ink);
  background: var(--assistant-veil);
  border-bottom: 1px solid var(--assistant-veil-line);
  -webkit-backdrop-filter: blur(14px) saturate(180%);
  backdrop-filter: blur(14px) saturate(180%);
  transition: transform 260ms cubic-bezier(0.23, 1, 0.32, 1), opacity 180ms linear;
}
.assistant-bar[data-hidden="true"] {
  transform: translateY(-100%);
  opacity: 0;
  pointer-events: none;
}
.assistant-bar-row {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 0 8px 0 12px;
}
.assistant-bar-identity {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1 1 auto;
}
.assistant-bar-title {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.012em;
  white-space: nowrap;
}
.assistant-bar-divider {
  width: 1px;
  height: 12px;
  flex: 0 0 auto;
  background: currentColor;
  opacity: 0.18;
}
.assistant-bar-meta {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--assistant-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.assistant-bar-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
}

/* The live orb: the one element on screen that is always about to change. */
.assistant-orb {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  border-radius: 999px;
  background: color-mix(in srgb, var(--assistant-muted) 18%, transparent);
}
.assistant-orb-core {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--assistant-muted);
  transition: background-color 200ms ease;
}
.assistant-orb[data-status="streaming"] { background: color-mix(in srgb, var(--assistant-ok) 20%, transparent); }
.assistant-orb[data-status="streaming"] .assistant-orb-core { background: var(--assistant-ok); animation: assistant-orb-pulse 1.5s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
.assistant-orb[data-status="connecting"] { background: color-mix(in srgb, var(--assistant-warn) 22%, transparent); }
.assistant-orb[data-status="connecting"] .assistant-orb-core { background: var(--assistant-warn); animation: assistant-orb-pulse 1.1s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
.assistant-orb[data-status="error"] { background: color-mix(in srgb, var(--assistant-danger) 20%, transparent); }
.assistant-orb[data-status="error"] .assistant-orb-core { background: var(--assistant-danger); }
@keyframes assistant-orb-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.7); }
}

/* State only speaks up when there is something to say. */
.assistant-bar-state {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 7px;
  margin-right: 4px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.01em;
  white-space: nowrap;
  color: var(--assistant-accent);
  background: color-mix(in srgb, var(--assistant-accent) 12%, transparent);
}
.assistant-bar-state[data-status="error"] {
  color: var(--assistant-danger);
  background: color-mix(in srgb, var(--assistant-danger) 12%, transparent);
}
.assistant-bar-state[data-status="connecting"] {
  color: #b45309;
  background: color-mix(in srgb, var(--assistant-warn) 18%, transparent);
}
.dark .assistant-bar-state[data-status="connecting"] { color: #fcd34d; }

.assistant-bar-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--assistant-muted);
  transition: background-color 140ms ease, color 140ms ease;
}
.assistant-bar-button.is-active {
  color: var(--assistant-accent);
  background: color-mix(in srgb, var(--assistant-accent) 12%, transparent);
}
.assistant-bar-badge {
  position: absolute;
  top: 1px;
  right: 0;
  min-width: 13px;
  height: 13px;
  padding: 0 3px;
  border-radius: 999px;
  background: var(--assistant-accent);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  line-height: 13px;
  text-align: center;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 0 0 2px var(--assistant-veil);
}
.assistant-bar-menu-root { position: relative; display: flex; }

/* The bar's own idea of an action is a 28px square: no text, no chrome. */
.assistant-bar .assistant-header-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: var(--assistant-muted);
  text-decoration: none;
  transition: background-color 140ms ease, color 140ms ease;
}

@media (hover: hover) and (pointer: fine) {
  .assistant-bar-button:hover,
  .assistant-bar .assistant-header-action:hover { background: color-mix(in srgb, var(--assistant-ink) 7%, transparent); color: var(--assistant-ink); }
  .assistant-bar .assistant-header-action:hover { color: var(--assistant-ink); }
}

/* --- Overflow menu --- */
.assistant-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 40;
  min-width: 216px;
  padding: 5px;
  background: var(--assistant-surface);
  border: 1px solid var(--assistant-line);
  border-radius: 12px;
  box-shadow: 0 18px 44px -14px rgba(8, 15, 30, 0.4), 0 2px 8px rgba(8, 15, 30, 0.08);
  transform-origin: top right;
  animation: assistant-menu-in 150ms cubic-bezier(0.23, 1, 0.32, 1) both;
}
@keyframes assistant-menu-in {
  from { opacity: 0; transform: translateY(-4px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.assistant-menu-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 32px;
  padding: 0 9px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--assistant-ink);
  font-size: 12px;
  text-align: left;
  transition: background-color 120ms ease;
}
.assistant-menu-icon { display: inline-flex; color: var(--assistant-muted); }
.assistant-menu-label { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.assistant-menu-count {
  flex: 0 0 auto;
  color: var(--assistant-muted);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}
.assistant-menu-item.is-active {
  color: var(--assistant-accent);
  background: color-mix(in srgb, var(--assistant-accent) 10%, transparent);
}
.assistant-menu-item.is-active .assistant-menu-icon { color: var(--assistant-accent); }
.assistant-menu-item.is-danger { color: var(--assistant-danger); }
.assistant-menu-item.is-danger .assistant-menu-icon { color: var(--assistant-danger); }
@media (hover: hover) and (pointer: fine) {
  .assistant-menu-item:not(:disabled):hover { background: color-mix(in srgb, var(--assistant-ink) 6%, transparent); }
  .assistant-menu-item.is-danger:not(:disabled):hover { background: color-mix(in srgb, var(--assistant-danger) 12%, transparent); }
}

/* --- Provider + context chips, on the bar's own surface --- */
.assistant-bar [data-testid="ai-provider-badge"] { flex: 0 0 auto; }
.assistant-bar [data-testid="ai-provider-badge"] > span:first-child {
  border-radius: 999px;
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 600;
  background: color-mix(in srgb, var(--assistant-accent) 12%, transparent);
  color: var(--assistant-accent);
}
.assistant-bar [data-testid="ai-providers"] {
  max-width: 110px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--assistant-muted);
  font-size: 10px;
}

/* ======================================================================
   Disclosures, transcript and messages
   ====================================================================== */
.assistant-disclosure { flex-shrink: 0; max-height: 34vh; overflow-y: auto; border-bottom: 1px solid var(--assistant-line); }
.assistant-settings { padding: 16px 18px; background: var(--assistant-surface); font-size: 12px; }
.assistant-settings h3 { font-size: 13px; font-weight: 600; margin-bottom: 6px; }
.assistant-settings p { color: var(--assistant-muted); line-height: 1.6; }
.assistant-tool-catalogue { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; margin-top: 12px; }
.assistant-tool-catalogue li { min-width: 0; padding: 9px; border: 1px solid var(--assistant-line); border-radius: 9px; background: var(--assistant-bg); }
.assistant-tool-catalogue li > span { font-size: 11px; font-weight: 600; }
.assistant-tool-catalogue li > p { margin-top: 3px; font-size: 10px; }
.assistant-context-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 12px 0; }
.assistant-context-facts > div { padding: 10px; border: 1px solid var(--assistant-line); border-radius: 10px; min-width: 0; }
.assistant-context-facts dt { color: var(--assistant-muted); font-size: 10px; text-transform: capitalize; }
.assistant-context-facts dd { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; margin-top: 3px; }
.assistant-session-row { border-color: var(--assistant-line); background: var(--assistant-bg); min-height: 52px; padding: 7px 9px; }
.assistant-transcript {
  padding: 54px 20px 24px;
  min-height: 100px;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  background: radial-gradient(ellipse at 50% 0, #3b82f606, transparent 60%);
}
.assistant-empty { min-height: 240px; padding: 32px 16px; color: var(--assistant-muted); }
.assistant-emblem { color: #fff; background: linear-gradient(145deg, #5b96ef, #285ab6); box-shadow: 0 12px 32px #2563eb24, inset 0 1px 0 #ffffff55; }
.assistant-empty h3 { color: var(--assistant-ink); font-size: 20px; font-weight: 600; letter-spacing: -.035em; line-height: 1.25; }
.assistant-empty p { color: var(--assistant-muted); font-size: 12px; line-height: 1.7; }
.assistant-section-label {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 5px;
  color: var(--assistant-muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.assistant-suggestions { flex-shrink: 0; padding: 9px 18px 10px; border-bottom: 1px solid var(--assistant-line); background: var(--assistant-bg); }
.assistant-suggestion {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px 4px 3px 9px;
  border: 1px solid var(--assistant-line);
  border-radius: 999px;
  background: var(--assistant-surface);
  color: var(--assistant-accent);
}
.assistant-suggestion-label { border: 0; background: none; padding: 0; font-size: 11px; color: inherit; }
.assistant-suggestion-dismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--assistant-muted);
}
.assistant-suggestion-dismiss:hover { background: color-mix(in srgb, var(--assistant-ink) 8%, transparent); color: var(--assistant-ink); }
.assistant-thinking-card {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 12px 0 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--assistant-accent) 22%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--assistant-accent) 5%, transparent);
}
.assistant-message { padding-bottom: 16px; }
.assistant-message + .assistant-message { margin-top: 12px; }
.assistant-message > div:first-child { padding: 0 3px; letter-spacing: .04em; }
.assistant-message-body { padding: 14px 4px; line-height: 1.75; overflow-wrap: anywhere; color: var(--assistant-ink); }
.assistant-message[data-role="user"] .assistant-message-body { padding: 12px 16px; background: var(--assistant-surface); border: 1px solid var(--assistant-line); border-radius: 14px 14px 4px 14px; }
.assistant-tool-call { padding: 9px 12px; border: 1px solid var(--assistant-line); border-radius: 9px; background: var(--assistant-surface); flex-wrap: wrap; }
.assistant-permission { padding: 12px; background: #f59e0b0d; border: 1px solid #f59e0b40; border-radius: 10px; }
.assistant-permission button { min-height: 30px; padding: 4px 10px; }
.assistant-control-error {
  flex-shrink: 0;
  padding: 7px 14px;
  border-top: 1px solid color-mix(in srgb, var(--assistant-danger) 30%, transparent);
  background: color-mix(in srgb, var(--assistant-danger) 10%, transparent);
  color: var(--assistant-danger);
  font-size: 11px;
}

/* ======================================================================
   The composer
   One card. The prompt on top, a single row of controls underneath: the
   run settings on the left, the send cluster flush right.
   ====================================================================== */
.assistant-composer { padding: 8px 14px 12px; flex-shrink: 0; background: var(--assistant-bg); }
.assistant-compose-frame {
  padding: 9px 9px 8px;
  background: var(--assistant-surface);
  border: 1px solid var(--assistant-line);
  border-radius: 14px;
  box-shadow: 0 1px 2px rgba(16, 43, 77, 0.04), 0 4px 14px -8px rgba(16, 43, 77, 0.12);
  transition: border-color 160ms ease, box-shadow 160ms ease;
}
.assistant-compose-frame:focus-within {
  border-color: color-mix(in srgb, var(--assistant-accent) 55%, var(--assistant-line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--assistant-accent) 12%, transparent);
}
.assistant-prompt {
  display: block;
  width: 100%;
  min-height: 44px;
  max-height: 180px;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  padding: 4px 6px 8px;
  font-size: 13px;
  line-height: 1.65;
  color: var(--assistant-ink);
}
.assistant-prompt::placeholder { color: var(--assistant-muted); }
.assistant-compose-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  padding: 0 2px;
}
.assistant-compose-tail {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.assistant-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  color: var(--assistant-muted);
  border: 0;
  border-radius: 8px;
  background: transparent;
  transition: background-color 140ms ease, color 140ms ease;
}
.assistant-attach { margin-left: -2px; }

/* --- Chips: agent, mode, permissions, thinking, model --- */
.assistant-chips { display: flex; align-items: center; gap: 2px; flex-wrap: wrap; min-width: 0; }
.assistant-chip-root { position: relative; display: flex; }
.assistant-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  height: 26px;
  padding: 0 7px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--assistant-muted);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}
.assistant-chip-icon { display: inline-flex; flex: 0 0 auto; opacity: 0.85; }
.assistant-chip-value { min-width: 0; max-width: 15ch; overflow: hidden; text-overflow: ellipsis; }
.assistant-chip-select {
  appearance: none;
  min-width: 0;
  max-width: 13ch;
  padding: 0;
  border: 0;
  outline: none;
  background: none;
  color: inherit;
  font: inherit;
  line-height: inherit;
  cursor: pointer;
}
.assistant-chip.is-disabled { opacity: 0.5; cursor: not-allowed; }
.assistant-chip-model { color: var(--assistant-ink); border-color: var(--assistant-line); background: var(--assistant-bg); }
.assistant-chip-model .assistant-chip-icon { color: var(--assistant-accent); opacity: 1; }

@media (hover: hover) and (pointer: fine) {
  .assistant-chip:not(.is-disabled):hover { color: var(--assistant-ink); background: color-mix(in srgb, var(--assistant-ink) 6%, transparent); }
  .assistant-chip-model:hover { border-color: color-mix(in srgb, var(--assistant-accent) 45%, var(--assistant-line)); }
}
.assistant-chip:focus-within {
  border-color: color-mix(in srgb, var(--assistant-accent) 55%, transparent);
  background: color-mix(in srgb, var(--assistant-accent) 8%, transparent);
}

/* --- Send cluster --- */
.assistant-context-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  min-width: 28px;
  padding: 0 7px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--assistant-muted);
  transition: background-color 140ms ease, color 140ms ease;
}
.assistant-context-chip[data-enabled="true"] { color: var(--assistant-accent); background: color-mix(in srgb, var(--assistant-accent) 10%, transparent); }
.assistant-context-dot { width: 5px; height: 5px; border-radius: 999px; background: currentColor; }
.assistant-character-count {
  color: var(--assistant-muted);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.assistant-character-count[data-over="true"] { color: var(--assistant-danger); font-weight: 600; }
.assistant-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: 9px;
  background: var(--assistant-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
.assistant-send:disabled { background: color-mix(in srgb, var(--assistant-accent) 32%, transparent); box-shadow: none; }
.assistant-send-icon { width: 28px; padding: 0; }
.assistant-stop { background: var(--assistant-ink); color: var(--assistant-surface); }
.assistant-composer-hint {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 4px 0;
  color: var(--assistant-muted);
  font-size: 9px;
}
@media (hover: hover) and (pointer: fine) {
  .assistant-context-chip:hover, .assistant-icon-button:hover { background: color-mix(in srgb, var(--assistant-ink) 6%, transparent); color: var(--assistant-ink); }
  .assistant-send:not(:disabled):hover { background: color-mix(in srgb, var(--assistant-accent) 84%, #000); }
}
.assistant-attachment {
  max-width: 100%;
  border: 1px solid var(--assistant-line);
  border-radius: 7px;
  padding: 4px 7px;
  background: var(--assistant-bg);
  color: var(--assistant-ink);
}
.assistant-attachment button { min-width: 24px; min-height: 24px; display: inline-flex; align-items: center; justify-content: center; }

/* --- Popovers and the jump-to-latest pill --- */
.assistant-popover {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  width: min(320px, calc(100vw - 48px));
  max-height: 320px;
  overflow-y: auto;
  background: var(--assistant-surface);
  color: var(--assistant-ink);
  border: 1px solid var(--assistant-line);
  border-radius: 12px;
  box-shadow: 0 16px 40px #00000026;
  z-index: 30;
  transform-origin: bottom left;
}
.assistant-jump-latest {
  position: absolute;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  background: var(--assistant-surface);
  color: var(--assistant-accent);
  border: 1px solid var(--assistant-line);
  box-shadow: 0 8px 20px #0f172a26;
  z-index: 5;
}
.assistant-jump-latest:hover { background: var(--assistant-accent); color: #fff; }

/* --- Shared interaction rules --- */
.assistant-surface button { transition: transform 120ms cubic-bezier(.23,1,.32,1), background-color 150ms ease, color 150ms ease, border-color 150ms ease; }
.assistant-surface button:active:not(:disabled) { transform: scale(.97); }
.assistant-surface button:disabled { cursor: not-allowed; opacity: .5; }
.assistant-surface :is(button, input, select, summary, a):focus-visible { outline: 2px solid var(--assistant-accent); outline-offset: 2px; }
.assistant-bar :is(button, a):focus-visible { outline-color: var(--assistant-accent); }

/* --- Context gauge, on the bar --- */
.assistant-context-gauge { display: inline-flex; align-items: center; gap: 4px; padding: 0 4px; color: var(--assistant-muted); font-size: 10px; font-variant-numeric: tabular-nums; }
.assistant-context-gauge[data-level="warn"] { color: #b45309; }
.assistant-context-gauge[data-level="full"] { color: var(--assistant-danger); }
.dark .assistant-context-gauge[data-level="warn"] { color: #fcd34d; }

/* --- Responsive: the docked panel is 520px, the page is not --- */
@media (max-width: 520px) {
  .assistant-chip-value { max-width: 10ch; }
  .assistant-chip-select { max-width: 9ch; }
  .assistant-composer-hint > span:last-child { display: none; }
}
@media (max-width: 420px) {
  .assistant-bar-row { padding: 0 6px 0 10px; gap: 6px; }
  .assistant-bar-meta, .assistant-bar-divider { display: none; }
  .assistant-chip-value { max-width: 7ch; }
  .assistant-chip-select { max-width: 7ch; }
  .assistant-transcript { padding: 50px 14px 20px; }
  .assistant-character-count:not([data-over="true"]) { display: none; }
  .assistant-composer-hint { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .assistant-surface *, .assistant-surface *::before, .assistant-surface *::after { animation: none !important; transition: none !important; }
  .assistant-surface button:active:not(:disabled) { transform: none; }
  .assistant-bar[data-hidden="true"] { transform: none; }
}
@media (prefers-reduced-transparency: reduce) {
  .assistant-surface * { backdrop-filter: none !important; }
  .assistant-bar { background: var(--assistant-bg); }
}
@media (prefers-contrast: more) {
  .assistant-surface { --assistant-muted: #354a65; --assistant-line: #6a7f99; }
  .dark .assistant-surface { --assistant-muted: #cbd8e9; --assistant-line: #a0b4cf; }
  .assistant-bar { border-bottom-color: var(--assistant-line); }
  .assistant-bar-button { color: var(--assistant-ink); }
  .assistant-menu-item { color: var(--assistant-ink); }
}

